entries[27632] = { ["name"] = "Terokks Federkiel", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein langer, schlanker Arakkoaspeer, der an einem messerscharfen Punkt zusammenläuft. Scheinbar wurde er aus nur einem Stück Metall gearbeitet und weist keine Spuren der Alterung auf.\"" }
entries[27633] = { ["name"] = "Terokks Maske", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine gefiederte Maske, deren Passform auf Arakkoagesichter zugeschnitten ist. Es scheint, als wäre sie für einen Arakkoa angefertigt worden, der größer sein muss, als alle, die ihr je zu Gesicht bekommen habt.\"" }
entries[27634] = { ["name"] = "Die Sage von Terokk", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine Schriftrolle, die Geschichten über das Leben des großen Arakkoahelden Terokk beinhaltet.\"" }
